-- ============================================================
-- RBAC catalog: permissions + 2120 roles + access (role_permissions)
-- Generated by scripts/gen-role-catalog-migration.mjs
-- Modules: 53 x levels: 8 x variants: 5 = 2120 roles
-- Permission slugs seeded: 313
-- Idempotent (safe to re-run)
-- ============================================================

-- 1) Ensure full permission catalog
ON CONFLICT (slug) DO NOTHING;

-- 2) Provision catalog roles and append module/level access
DO $$
DECLARE
  v_modules text[] := ARRAY['dashboard', 'production', 'mes', 'qr', 'lbl', 'printing', 'print', 'packing', 'pkg', 'ast', 'inventory', 'products', 'procurement', 'srm', 'scm', 'logistics', 'crm', 'sales', 'billing', 'invoices', 'dispatch', 'dsp', 'fleet', 'finance', 'payroll', 'hr', 'ta', 'wfm', 'att', 'profile', 'wid', 'di', 'uw', 'iam', 'users', 'sd', 'hc', 'comm', 'media', 'brand', 'reports', 'audit', 'eal', 'fraud', 'verification', 'notifications', 'settings', 'intg', 'ppm', 'ec', 'tenant', 'security', 'distributors'];
  v_levels  text[] := ARRAY['viewer', 'clerk', 'operator', 'specialist', 'supervisor', 'manager', 'director', 'admin'];
  v_variants text[] := ARRAY['core', 'east', 'west', 'central', 'remote'];
  v_company uuid;
  v_mod text;
  v_level text;
  v_variant text;
  v_slug text;
  v_name text;
  v_role_id uuid;
  v_created int := 0;
  v_links int := 0;
  v_prefix text;
BEGIN
  SELECT id INTO v_company
  FROM companies
  WHERE id = 'a0000000-0000-4000-8000-000000000001';

  FOREACH v_variant IN ARRAY v_variants LOOP
    FOREACH v_mod IN ARRAY v_modules LOOP
      FOREACH v_level IN ARRAY v_levels LOOP
        v_slug := 'catalog_' || v_mod || '_' || v_level || '_' || v_variant;
        v_name := initcap(replace(v_mod, '_', ' '))
          || ' '
          || initcap(v_level)
          || ' ('
          || initcap(v_variant)
          || ')';

        SELECT id INTO v_role_id
        FROM roles
        WHERE slug = v_slug
          AND deleted_at IS NULL
        LIMIT 1;

        IF v_role_id IS NULL THEN
            company_id, name, slug, description,
            is_system, is_active, role_category
          )
          VALUES (
            v_company,
            v_name,
            v_slug,
            'Catalog role — '
              || v_mod || ' ' || v_level || ' (' || v_variant
              || '). Seeded for RBAC least-privilege assignment.',
            true,
            true,
            'system'
          )
          RETURNING id INTO v_role_id;
          v_created := v_created + 1;
        END IF;

        -- Baseline access every catalog role gets
        SELECT v_role_id, p.id
        FROM permissions p
        WHERE p.slug IN (
          'dashboard.view',
          'notifications.view',
          'profile.self',
          'profile.view'
        )
        ON CONFLICT DO NOTHING;

        -- Module prefix for permission matching
        v_prefix := v_mod;

        -- Module-scoped access by level
        IF v_level IN ('viewer', 'clerk') THEN
          SELECT v_role_id, p.id
          FROM permissions p
          WHERE p.slug NOT LIKE 'platform.%'
            AND (
              p.slug = v_prefix || '.view'
              OR p.slug LIKE v_prefix || '.%.view'
              OR (v_mod = 'reports' AND p.slug IN ('reports.view', 'reports.export'))
              OR (v_mod = 'audit' AND p.slug IN ('audit.view', 'eal.view'))
              OR (v_mod = 'printing' AND p.slug IN ('print.view', 'printing.create'))
              OR (v_mod = 'print' AND p.slug = 'print.view')
            )
          ON CONFLICT DO NOTHING;

        ELSIF v_level IN ('operator', 'specialist') THEN
          SELECT v_role_id, p.id
          FROM permissions p
          WHERE p.slug NOT LIKE 'platform.%'
            AND (
              p.slug LIKE v_prefix || '.%'
            )
            AND (
              p.slug LIKE '%.view'
              OR p.slug LIKE '%.create'
              OR p.slug LIKE '%.operate'
              OR p.slug LIKE '%.clock'
              OR p.slug LIKE '%.field'
              OR p.slug LIKE '%.submit'
              OR p.slug LIKE '%.print'
              OR p.slug LIKE '%.move'
              OR p.slug LIKE '%.track'
              OR p.slug LIKE '%.design'
              OR p.slug LIKE '%.agent'
              OR p.slug LIKE '%.recruit'
            )
          ON CONFLICT DO NOTHING;

        ELSIF v_level IN ('supervisor', 'manager') THEN
          SELECT v_role_id, p.id
          FROM permissions p
          WHERE p.slug NOT LIKE 'platform.%'
            AND p.slug LIKE v_prefix || '.%'
            AND (
              p.slug LIKE '%.view'
              OR p.slug LIKE '%.manage'
              OR p.slug LIKE '%.operate'
              OR p.slug LIKE '%.create'
              OR p.slug LIKE '%.approve'
              OR p.slug LIKE '%.export'
              OR p.slug LIKE '%.edit'
              OR p.slug LIKE '%.process'
              OR p.slug LIKE '%.post'
              OR p.slug LIKE '%.collect'
            )
          ON CONFLICT DO NOTHING;

        ELSIF v_level = 'director' THEN
          SELECT v_role_id, p.id
          FROM permissions p
          WHERE p.slug NOT LIKE 'platform.%'
            AND (
              p.slug LIKE v_prefix || '.%'
              OR p.slug IN ('reports.view', 'reports.dashboards', 'reports.kpis')
            )
          ON CONFLICT DO NOTHING;

        ELSIF v_level = 'admin' THEN
          SELECT v_role_id, p.id
          FROM permissions p
          WHERE p.slug NOT LIKE 'platform.%'
            AND (
              p.slug LIKE v_prefix || '.%'
              OR p.slug IN ('settings.view', 'reports.view')
            )
          ON CONFLICT DO NOTHING;
        END IF;

      END LOOP;
    END LOOP;
  END LOOP;

  -- 3) Super administrator gets every non-platform permission (append)
  SELECT r.id, p.id
  FROM roles r
  CROSS JOIN permissions p
  WHERE r.slug = 'super_administrator'
    AND p.slug NOT LIKE 'platform.%'
  ON CONFLICT DO NOTHING;

  -- 4) Every active role has dashboard.view (append baseline)
  SELECT r.id, p.id
  FROM roles r
  CROSS JOIN permissions p
  WHERE COALESCE(r.is_active, true) = true
    AND r.deleted_at IS NULL
    AND p.slug = 'dashboard.view'
  ON CONFLICT DO NOTHING;

  -- 5) Existing seed system roles: append module-aligned access where empty-ish
  --    (managing_director gets broad view/manage across business modules)
  SELECT r.id, p.id
  FROM roles r
  CROSS JOIN permissions p
  WHERE r.slug = 'managing_director'
    AND p.slug NOT LIKE 'platform.%'
    AND (
      p.slug LIKE '%.view'
      OR p.slug LIKE '%.manage'
      OR p.slug LIKE '%.approve'
      OR p.slug LIKE '%.export'
      OR p.slug IN ('dashboard.view', 'reports.dashboards', 'reports.kpis')
    )
  ON CONFLICT DO NOTHING;

  SELECT r.id, p.id
  FROM roles r
  CROSS JOIN permissions p
  WHERE r.slug IN ('auditor', 'read_only')
    AND (
      p.slug LIKE '%.view'
      OR p.slug IN (
        'dashboard.view',
        'reports.view',
        'reports.export',
        'audit.view',
        'eal.view'
      )
    )
    AND p.slug NOT LIKE 'platform.%'
  ON CONFLICT DO NOTHING;

  GET DIAGNOSTICS v_links = ROW_COUNT;
  RAISE NOTICE 'Catalog roles created this run: % (target total catalog slugs: %)',
    v_created, 2120;
END $$;

